-- The read model (docs/DEV.md, "Query the data with SQL"; ready-made queries in server/deploy/browse.sql):
-- typed views over the JSONB records, so the data reads with plain SQL. One view per core record
-- collection (v_people, v_comp, v_jobs, ...), list views (v_checklist_tasks, v_application_stages,
-- v_pay_runs), journeys across them (v_current_job, v_hire_journey, v_pipeline_funnel,
-- v_headcount_by_month) and v_integrity_problems, the checks of src/domain/integrity.ts as rows.
--
-- Generated by `npm run server:gen-sql -- --read-model` from server/src/readmodel/spec.ts and the checks
-- in src/domain/integrity.ts; never edit it by hand. A later change to either ships as a new migration
-- whose body is the generator's whole output: `npm run server:gen-sql -- --read-model --write`
-- saves it as the next number. It drops every read-model view and creates them all again, so an applied
-- migration never changes. readmodel.test.ts fails while the newest NNN_read_model.sql differs from the
-- generator.
--
-- Every view: workspace_id first (filter on it to read one company); security_invoker, so a login reads
-- through a view only what it may read in the tables (needs Postgres 15 or newer); reads only the record
-- tables, workspace_docs and workspaces, never users, sessions, trusted_devices or invites; plain views,
-- no triggers, nothing on the write path (no role keeps a write right on them). The server's own role
-- reads them through its default privileges (server/deploy/postgres-setup.sql); the read-only login gets
-- them at the end of this file when it exists, and from server/deploy/viewer-role.sql.

-- Postgres 15 or newer first: the views read with the reader's own rights (security_invoker), which older
-- versions refuse. Stopping here leaves the database as it was.
DO $$
BEGIN
  IF current_setting('server_version_num')::int < 150000 THEN
    RAISE EXCEPTION 'First Twenty needs Postgres 15 or newer (this server runs %). docs/SERVER.md, "Before you start", says how to get it.', current_setting('server_version');
  END IF;
END
$$;

-- Views of an earlier read model go first (one statement, so views that read other views go together).
DROP VIEW IF EXISTS v_integrity_problems, v_headcount_by_month, v_pipeline_funnel, v_hire_journey, v_current_job, v_pay_runs, v_application_stages, v_checklist_tasks, v_activity, v_documents, v_time_off_requests, v_grants, v_checklists, v_offers, v_applications, v_candidates, v_jobs, v_comp, v_people;

-- Guarded casts: text that is not a value of the type gives NULL instead of failing the whole query
-- (an empty string, junk, a day such as Feb 30, a time zone offset past 15:59). Dates must be 'YYYY-MM-DD'
-- (src/domain/paths.ts asDate agrees), timestamps full ISO with a zone, numbers JSON numbers.
CREATE OR REPLACE FUNCTION ft_as_date(v text) RETURNS date
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    CASE WHEN substr(v, 1, 4)::int >= 1
          AND substr(v, 6, 2)::int BETWEEN 1 AND 12
          AND substr(v, 9, 2)::int BETWEEN 1 AND
              CASE WHEN substr(v, 6, 2)::int = 2 THEN
                     CASE WHEN (substr(v, 1, 4)::int % 4 = 0 AND substr(v, 1, 4)::int % 100 <> 0) OR substr(v, 1, 4)::int % 400 = 0 THEN 29 ELSE 28 END
                   WHEN substr(v, 6, 2)::int IN (4, 6, 9, 11) THEN 30
                   ELSE 31 END
      THEN make_date(substr(v, 1, 4)::int, substr(v, 6, 2)::int, substr(v, 9, 2)::int)
    END
  END
$$;

CREATE OR REPLACE FUNCTION ft_as_timestamptz(v text) RETURNS timestamptz
  LANGUAGE sql STABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9]([.][0-9]{1,6})?)?(Z|[+-](0[0-9]|1[0-5]):?[0-5][0-9])$'
               AND public.ft_as_date(substr(v, 1, 10)) IS NOT NULL
    THEN v::timestamptz END
$$;

CREATE OR REPLACE FUNCTION ft_as_num(v text) RETURNS numeric
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN v ~ '^-?[0-9]{1,30}([.][0-9]{1,30})?([eE][-+]?[0-9]{1,3})?$' THEN v::numeric END
$$;

CREATE OR REPLACE FUNCTION ft_as_int(v text) RETURNS integer
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN v ~ '^-?[0-9]{1,9}([.]0+)?$' THEN v::numeric::integer END
$$;

CREATE OR REPLACE FUNCTION ft_as_bool(v text) RETURNS boolean
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE v WHEN 'true' THEN true WHEN 'false' THEN false END
$$;

-- A list or an object, or an empty one when the value is something else, so reading a malformed record
-- never fails (jsonb_array_elements and jsonb_each refuse other values).
CREATE OR REPLACE FUNCTION ft_array(v jsonb) RETURNS jsonb
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'array' THEN v ELSE '[]'::jsonb END
$$;

CREATE OR REPLACE FUNCTION ft_object(v jsonb) RETURNS jsonb
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  SELECT CASE WHEN jsonb_typeof(v) = 'object' THEN v ELSE '{}'::jsonb END
$$;

-- Today for the views that depend on it (v_current_job, v_headcount_by_month): the date in the setting
-- first_twenty.today when the session sets one (SET first_twenty.today = '2026-12-31' reads them as of
-- that day), else today in Pacific time, the app's own day, whatever time zone the server or session uses.
CREATE OR REPLACE FUNCTION ft_today() RETURNS date
  LANGUAGE sql STABLE PARALLEL SAFE
AS $$
  SELECT coalesce(public.ft_as_date(current_setting('first_twenty.today', true)), (now() AT TIME ZONE 'America/Los_Angeles')::date)
$$;

CREATE VIEW v_people WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       ft_as_int(r.data ->> 'hireNumber') AS hire_number,
       NULLIF(r.data ->> 'firstName', '') AS first_name,
       NULLIF(r.data ->> 'lastName', '') AS last_name,
       NULLIF(r.data ->> 'preferredName', '') AS preferred_name,
       concat_ws(' ', coalesce(NULLIF(r.data ->> 'preferredName', ''), NULLIF(r.data ->> 'firstName', '')), NULLIF(r.data ->> 'lastName', '')) AS full_name,
       NULLIF(r.data ->> 'workEmail', '') AS work_email,
       NULLIF(r.data ->> 'title', '') AS title,
       NULLIF(r.data ->> 'departmentId', '') AS department_id,
       (SELECT NULLIF(t.data ->> 'name', '') FROM departments t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'departmentId') AS department_name,
       NULLIF(r.data ->> 'familyId', '') AS family_id,
       NULLIF(r.data ->> 'levelId', '') AS level_id,
       (SELECT NULLIF(t.data ->> 'code', '') FROM levels t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'levelId') AS level_code,
       NULLIF(r.data ->> 'managerId', '') AS manager_id,
       NULLIF(r.data ->> 'locationId', '') AS location_id,
       (SELECT NULLIF(t.data ->> 'name', '') FROM locations t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'locationId') AS location_name,
       NULLIF(r.data ->> 'workMode', '') AS work_mode,
       NULLIF(r.data ->> 'homeCity', '') AS home_city,
       NULLIF(r.data ->> 'homeState', '') AS home_state,
       NULLIF(r.data ->> 'employmentType', '') AS employment_type,
       ft_as_num(r.data ->> 'hoursPerWeek') AS hours_per_week,
       NULLIF(r.data ->> 'flsa', '') AS flsa,
       NULLIF(r.data ->> 'exemptionBasis', '') AS exemption_basis,
       ft_as_date(r.data ->> 'startDate') AS start_date,
       ft_as_date(r.data ->> 'endDate') AS end_date,
       ft_as_bool(r.data ->> 'isFounder') AS is_founder,
       NULLIF(r.data ->> 'payrollId', '') AS payroll_id,
       NULLIF(r.data ->> 'fromCandidateId', '') AS from_candidate_id,
       NULLIF(r.data ->> 'fromApplicationId', '') AS from_application_id,
       NULLIF(r.data ->> 'rehireOfPersonId', '') AS rehire_of_person_id,
       NULLIF(r.data ->> 'fromContractorId', '') AS from_contractor_id,
       NULLIF(r.data #>> '{separation,type}', '') AS separation_type,
       ft_as_date(r.data #>> '{separation,noticeGivenOn}') AS notice_given_on,
       ft_as_date(r.data #>> '{separation,lastDay}') AS last_day,
       NULLIF(r.data #>> '{backgroundCheck,status}', '') AS background_check_status,
       ft_as_date(r.data ->> 'i9ReverifyOn') AS i9_reverify_on,
       r.version,
       r.updated_at
  FROM people r;
COMMENT ON VIEW v_people IS 'Employees (W-2), one row per person record. Contractors and advisors are not here.';

CREATE VIEW v_comp WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       ft_as_date(r.data ->> 'effectiveOn') AS effective_on,
       NULLIF(r.data ->> 'reason', '') AS reason,
       NULLIF(r.data ->> 'payType', '') AS pay_type,
       ft_as_num(r.data ->> 'salary') AS salary,
       ft_as_num(r.data ->> 'hourlyRate') AS hourly_rate,
       ft_as_num(r.data ->> 'variablePct') AS variable_pct,
       NULLIF(r.data ->> 'title', '') AS title,
       NULLIF(r.data ->> 'levelId', '') AS level_id,
       NULLIF(r.data ->> 'managerId', '') AS manager_id,
       NULLIF(r.data ->> 'departmentId', '') AS department_id,
       NULLIF(r.data ->> 'flsa', '') AS flsa,
       NULLIF(r.data ->> 'exemptionBasis', '') AS exemption_basis,
       NULLIF(r.data ->> 'exceptionReason', '') AS exception_reason,
       NULLIF(r.data ->> 'approvedById', '') AS approved_by_id,
       ft_as_date(r.data ->> 'approvedOn') AS approved_on,
       ft_as_date(r.data ->> 'appliedOn') AS applied_on,
       ft_as_bool(r.data ->> 'scheduled') AS scheduled,
       r.version,
       r.updated_at
  FROM comp r;
COMMENT ON VIEW v_comp IS 'Job and pay history: one row per effective-dated change. The newest row on or before a date is the job and pay on that date.';

CREATE VIEW v_jobs WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'title', '') AS title,
       NULLIF(r.data ->> 'status', '') AS status,
       NULLIF(r.data ->> 'priority', '') AS priority,
       NULLIF(r.data ->> 'departmentId', '') AS department_id,
       (SELECT NULLIF(t.data ->> 'name', '') FROM departments t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'departmentId') AS department_name,
       NULLIF(r.data ->> 'familyId', '') AS family_id,
       NULLIF(r.data ->> 'levelId', '') AS level_id,
       NULLIF(r.data ->> 'hiringManagerId', '') AS hiring_manager_id,
       NULLIF(r.data ->> 'workMode', '') AS work_mode,
       NULLIF(r.data ->> 'employmentType', '') AS employment_type,
       NULLIF(r.data ->> 'flsa', '') AS flsa,
       ft_as_num(r.data ->> 'payMin') AS pay_min,
       ft_as_num(r.data ->> 'payMax') AS pay_max,
       ft_as_num(r.data ->> 'equityMinPct') AS equity_min_pct,
       ft_as_num(r.data ->> 'equityMaxPct') AS equity_max_pct,
       ft_as_date(r.data ->> 'openedOn') AS opened_on,
       ft_as_date(r.data ->> 'postedOn') AS posted_on,
       ft_as_date(r.data ->> 'closedOn') AS closed_on,
       ft_as_date(r.data ->> 'targetStart') AS target_start,
       NULLIF(r.data ->> 'planSlotId', '') AS plan_slot_id,
       NULLIF(r.data ->> 'roleTemplateId', '') AS role_template_id,
       ft_as_bool(r.data ->> 'isBackfill') AS is_backfill,
       NULLIF(r.data ->> 'backfillForPersonId', '') AS backfill_for_person_id,
       NULLIF(r.data ->> 'sponsorship', '') AS sponsorship,
       ft_as_bool(r.data ->> 'backgroundCheck') AS background_check,
       ft_as_num(r.data ->> 'referralBonus') AS referral_bonus,
       jsonb_array_length(ft_array(r.data -> 'stages')) AS stage_count,
       jsonb_array_length(ft_array(r.data -> 'panelIds')) AS panel_size,
       NULLIF(r.data #>> '{requisition,status}', '') AS requisition_status,
       NULLIF(r.data #>> '{requisition,requestedById}', '') AS requisition_requested_by_id,
       ft_as_date(r.data #>> '{requisition,requestedOn}') AS requisition_requested_on,
       r.version,
       r.updated_at
  FROM jobs r;
COMMENT ON VIEW v_jobs IS 'Jobs (requisitions and postings), with the posted pay range.';

CREATE VIEW v_candidates WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'firstName', '') AS first_name,
       NULLIF(r.data ->> 'lastName', '') AS last_name,
       NULLIF(r.data ->> 'email', '') AS email,
       NULLIF(r.data ->> 'location', '') AS location,
       NULLIF(r.data ->> 'timezone', '') AS timezone,
       NULLIF(r.data ->> 'currentTitle', '') AS current_title,
       NULLIF(r.data ->> 'currentCompany', '') AS current_company,
       NULLIF(r.data ->> 'source', '') AS source,
       NULLIF(r.data ->> 'sourceDetail', '') AS source_detail,
       NULLIF(r.data ->> 'referrerId', '') AS referrer_id,
       ft_as_num(r.data ->> 'desiredPay') AS desired_pay,
       NULLIF(r.data ->> 'desiredPayUnit', '') AS desired_pay_unit,
       NULLIF(r.data ->> 'sponsorship', '') AS sponsorship,
       NULLIF(array_to_string(ARRAY(SELECT jsonb_array_elements_text(ft_array(r.data -> 'tags'))), ', '), '') AS tags,
       ft_as_date(r.data ->> 'createdOn') AS created_on,
       ft_as_date(r.data ->> 'retainUntil') AS retain_until,
       ft_as_bool(r.data ->> 'archived') AS archived,
       ft_as_date(r.data ->> 'anonymizedOn') AS anonymized_on,
       r.version,
       r.updated_at
  FROM candidates r;
COMMENT ON VIEW v_candidates IS 'Candidates. Desired pay only: California bans asking about current or past pay.';

CREATE VIEW v_applications WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'candidateId', '') AS candidate_id,
       NULLIF(r.data ->> 'jobId', '') AS job_id,
       NULLIF(r.data ->> 'stageId', '') AS stage_id,
       (SELECT NULLIF(s.el ->> 'name', '') FROM jobs j CROSS JOIN LATERAL jsonb_array_elements(ft_array(j.data -> 'stages')) AS s(el)
            WHERE j.workspace_id = r.workspace_id AND j.id = r.data ->> 'jobId' AND s.el ->> 'id' = r.data ->> 'stageId' LIMIT 1) AS stage_name,
       (SELECT NULLIF(s.el ->> 'kind', '') FROM jobs j CROSS JOIN LATERAL jsonb_array_elements(ft_array(j.data -> 'stages')) AS s(el)
            WHERE j.workspace_id = r.workspace_id AND j.id = r.data ->> 'jobId' AND s.el ->> 'id' = r.data ->> 'stageId' LIMIT 1) AS stage_kind,
       NULLIF(r.data ->> 'status', '') AS status,
       ft_as_date(r.data ->> 'appliedOn') AS applied_on,
       ft_as_date(r.data ->> 'stageEnteredOn') AS stage_entered_on,
       greatest(jsonb_array_length(ft_array(r.data -> 'history')) - 1, 0) AS stage_moves,
       ft_as_date(r.data #>> '{nextStep,dueOn}') AS next_step_due_on,
       NULLIF(r.data #>> '{nextStep,ownerId}', '') AS next_step_owner_id,
       ft_as_date(r.data ->> 'snoozedUntil') AS snoozed_until,
       ft_as_date(r.data ->> 'lastContactOn') AS last_contact_on,
       NULLIF(r.data ->> 'outcomeReason', '') AS outcome_reason,
       ft_as_date(r.data ->> 'closedOn') AS closed_on,
       ft_as_date(r.data ->> 'notifiedOn') AS notified_on,
       ft_as_date(r.data ->> 'conditionalOfferOn') AS conditional_offer_on,
       r.version,
       r.updated_at
  FROM applications r;
COMMENT ON VIEW v_applications IS 'Applications: one candidate for one job, with the stage it is in.';

CREATE VIEW v_offers WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'applicationId', '') AS application_id,
       NULLIF(r.data ->> 'candidateId', '') AS candidate_id,
       NULLIF(r.data ->> 'jobId', '') AS job_id,
       ft_as_int(r.data ->> 'version') AS offer_version,
       NULLIF(r.data ->> 'status', '') AS status,
       NULLIF(r.data ->> 'title', '') AS title,
       NULLIF(r.data ->> 'levelId', '') AS level_id,
       NULLIF(r.data ->> 'familyId', '') AS family_id,
       NULLIF(r.data ->> 'departmentId', '') AS department_id,
       NULLIF(r.data ->> 'managerId', '') AS manager_id,
       NULLIF(r.data ->> 'locationId', '') AS location_id,
       NULLIF(r.data ->> 'workMode', '') AS work_mode,
       NULLIF(r.data ->> 'employmentType', '') AS employment_type,
       ft_as_num(r.data ->> 'hoursPerWeek') AS hours_per_week,
       NULLIF(r.data ->> 'flsa', '') AS flsa,
       NULLIF(r.data ->> 'exemptionBasis', '') AS exemption_basis,
       NULLIF(r.data ->> 'payType', '') AS pay_type,
       ft_as_num(r.data ->> 'salary') AS salary,
       ft_as_num(r.data ->> 'hourlyRate') AS hourly_rate,
       ft_as_num(r.data ->> 'variablePct') AS variable_pct,
       ft_as_num(r.data ->> 'signOnBonus') AS sign_on_bonus,
       NULLIF(r.data ->> 'equityType', '') AS equity_type,
       ft_as_num(r.data ->> 'equityShares') AS equity_shares,
       ft_as_int(r.data ->> 'vestingMonths') AS vesting_months,
       ft_as_int(r.data ->> 'cliffMonths') AS cliff_months,
       ft_as_date(r.data ->> 'startDate') AS start_date,
       ft_as_date(r.data ->> 'expiresOn') AS expires_on,
       NULLIF(array_to_string(ARRAY(SELECT jsonb_array_elements_text(ft_array(r.data -> 'contingencies'))), ', '), '') AS contingencies,
       ft_as_date(r.data ->> 'createdOn') AS created_on,
       NULLIF(r.data ->> 'draftedById', '') AS drafted_by_id,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'approvals')) AS i(el) WHERE i.el ->> 'decision' = 'approved') AS approval_count,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'approvals')) AS i(el) WHERE i.el ->> 'decision' = 'changes_requested') AS changes_requested_count,
       ft_as_date(r.data ->> 'sentOn') AS sent_on,
       ft_as_date(r.data ->> 'decidedOn') AS decided_on,
       NULLIF(r.data #>> '{backgroundCheck,status}', '') AS background_check_status,
       NULLIF(r.data #>> '{backgroundCheck,result}', '') AS background_check_result,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       r.version,
       r.updated_at
  FROM offers r;
COMMENT ON VIEW v_offers IS 'Offers, one row per offer record (offer_version counts revisions of one offer).';

CREATE VIEW v_checklists WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       NULLIF(r.data ->> 'kind', '') AS kind,
       NULLIF(r.data ->> 'templateId', '') AS template_id,
       ft_as_date(r.data ->> 'anchorDate') AS anchor_date,
       NULLIF(r.data ->> 'separationType', '') AS separation_type,
       ft_as_date(r.data ->> 'createdOn') AS created_on,
       ft_as_date(r.data ->> 'completedOn') AS completed_on,
       jsonb_array_length(ft_array(r.data -> 'tasks')) AS tasks_total,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'tasks')) AS i(el) WHERE i.el ->> 'status' = 'done') AS tasks_done,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'tasks')) AS i(el) WHERE i.el ->> 'status' = 'open') AS tasks_open,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'tasks')) AS i(el) WHERE i.el ->> 'status' = 'not_applicable') AS tasks_not_applicable,
       (SELECT count(*)::int FROM jsonb_array_elements(ft_array(r.data -> 'tasks')) AS i(el) WHERE i.el ->> 'status' = 'open' AND i.el ->> 'statutory' = 'true') AS statutory_open,
       (SELECT min(ft_as_date(i.el ->> 'dueOn')) FROM jsonb_array_elements(ft_array(r.data -> 'tasks')) AS i(el) WHERE i.el ->> 'status' = 'open') AS next_due_on,
       r.version,
       r.updated_at
  FROM checklists r;
COMMENT ON VIEW v_checklists IS 'Onboarding, offboarding, new-state, leave and change checklists, with task counts.';

CREATE VIEW v_grants WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'personId', '') AS holder_id,
       NULLIF(r.data ->> 'holderType', '') AS holder_type,
       NULLIF(r.data ->> 'type', '') AS grant_type,
       NULLIF(r.data ->> 'status', '') AS status,
       ft_as_num(r.data ->> 'shares') AS shares,
       ft_as_num(r.data ->> 'strikePrice') AS strike_price,
       ft_as_date(r.data ->> 'vestingStart') AS vesting_start,
       ft_as_int(r.data ->> 'cliffMonths') AS cliff_months,
       ft_as_int(r.data ->> 'vestingMonths') AS vesting_months,
       ft_as_date(r.data ->> 'proposedOn') AS proposed_on,
       ft_as_date(r.data ->> 'boardApprovedOn') AS board_approved_on,
       ft_as_num(r.data ->> 'exercisedShares') AS exercised_shares,
       ft_as_num(r.data ->> 'cancelledShares') AS cancelled_shares,
       ft_as_date(r.data ->> 'cancelledOn') AS cancelled_on,
       ft_as_bool(r.data ->> 'earlyExercise') AS early_exercise,
       ft_as_date(r.data ->> 'election83bDueOn') AS election_83b_due_on,
       ft_as_int(r.data ->> 'postTerminationExerciseDays') AS post_termination_exercise_days,
       NULLIF(r.data ->> 'fromOfferId', '') AS from_offer_id,
       r.version,
       r.updated_at
  FROM grants r;
COMMENT ON VIEW v_grants IS 'Equity grants. Holders are employees, advisors, contractors, or candidates while an offer is out (holder_type).';

CREATE VIEW v_time_off_requests WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       NULLIF(r.data ->> 'policyId', '') AS policy_id,
       (SELECT NULLIF(t.data ->> 'name', '') FROM time_off_policies t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'policyId') AS policy_name,
       (SELECT NULLIF(t.data ->> 'kind', '') FROM time_off_policies t WHERE t.workspace_id = r.workspace_id AND t.id = r.data ->> 'policyId') AS policy_kind,
       ft_as_date(r.data ->> 'startDate') AS start_date,
       ft_as_date(r.data ->> 'endDate') AS end_date,
       NULLIF(r.data ->> 'partial', '') AS partial,
       ft_as_num(r.data ->> 'hours') AS hours,
       NULLIF(r.data ->> 'status', '') AS status,
       ft_as_date(r.data ->> 'requestedOn') AS requested_on,
       NULLIF(r.data ->> 'approverId', '') AS approver_id,
       ft_as_date(r.data ->> 'decidedOn') AS decided_on,
       NULLIF(r.data ->> 'recordedUnpaidFrom', '') AS recorded_unpaid_from,
       r.version,
       r.updated_at
  FROM time_off_requests r;
COMMENT ON VIEW v_time_off_requests IS 'Time off requests. Notes are left out: they can hold private reasons.';

CREATE VIEW v_documents WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       NULLIF(r.data ->> 'type', '') AS document_type,
       NULLIF(r.data ->> 'name', '') AS name,
       NULLIF(r.data ->> 'status', '') AS status,
       ft_as_date(r.data ->> 'date') AS dated_on,
       NULLIF(r.data ->> 'link', '') AS link,
       ft_as_date(r.data ->> 'retainUntil') AS retain_until,
       r.version,
       r.updated_at
  FROM documents r;
COMMENT ON VIEW v_documents IS 'Documents tracked as status, date and link (never the file).';

CREATE VIEW v_activity WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id,
       ft_as_timestamptz(r.data ->> 'at') AS happened_at,
       NULLIF(r.data ->> 'actorId', '') AS actor_id,
       NULLIF(r.data ->> 'viewingAs', '') AS viewing_as,
       NULLIF(r.data ->> 'entityType', '') AS entity_type,
       NULLIF(r.data ->> 'entityId', '') AS entity_id,
       NULLIF(r.data ->> 'relatedId', '') AS related_id,
       NULLIF(r.data ->> 'kind', '') AS kind,
       NULLIF(r.data ->> 'text', '') AS text,
       r.version,
       r.updated_at
  FROM activity r;
COMMENT ON VIEW v_activity IS 'The activity log: who did what to which record, newest last.';

CREATE VIEW v_checklist_tasks WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id AS checklist_id,
       NULLIF(x.el ->> 'id', '') AS id,
       x.n::int AS ordinal,
       NULLIF(r.data ->> 'personId', '') AS person_id,
       NULLIF(r.data ->> 'kind', '') AS checklist_kind,
       NULLIF(x.el ->> 'title', '') AS title,
       NULLIF(x.el ->> 'status', '') AS status,
       ft_as_date(x.el ->> 'dueOn') AS due_on,
       ft_as_date(x.el ->> 'doneOn') AS done_on,
       NULLIF(x.el ->> 'doneById', '') AS done_by_id,
       NULLIF(x.el ->> 'ownerRole', '') AS owner_role,
       NULLIF(x.el ->> 'assigneeId', '') AS assignee_id,
       NULLIF(x.el ->> 'category', '') AS category,
       ft_as_bool(x.el ->> 'statutory') AS statutory,
       NULLIF(x.el #>> '{citation,label}', '') AS citation,
       NULLIF(x.el ->> 'templateTaskId', '') AS template_task_id
  FROM checklists r
 CROSS JOIN LATERAL jsonb_array_elements(ft_array(r.data -> 'tasks')) WITH ORDINALITY AS x(el, n);
COMMENT ON VIEW v_checklist_tasks IS 'Checklist tasks, one row per task, with its checklist.';

CREATE VIEW v_application_stages WITH (security_invoker = true) AS
SELECT r.workspace_id,
       r.id AS application_id,
       x.n::int AS ordinal,
       NULLIF(r.data ->> 'candidateId', '') AS candidate_id,
       NULLIF(r.data ->> 'jobId', '') AS job_id,
       NULLIF(x.el ->> 'stageId', '') AS stage_id,
       ft_as_date(x.el ->> 'at') AS entered_on,
       NULLIF(x.el ->> 'byId', '') AS moved_by_id
  FROM applications r
 CROSS JOIN LATERAL jsonb_array_elements(ft_array(r.data -> 'history')) WITH ORDINALITY AS x(el, n);
COMMENT ON VIEW v_application_stages IS 'Every stage move of every application, in order (ordinal 1 is where it started).';

CREATE VIEW v_pay_runs WITH (security_invoker = true) AS
SELECT d.workspace_id,
       x.n::int AS ordinal,
       ft_as_date(x.el ->> 'periodStart') AS period_start,
       ft_as_date(x.el ->> 'periodEnd') AS period_end,
       ft_as_date(x.el ->> 'payday') AS payday,
       ft_as_date(x.el ->> 'submittedOn') AS submitted_on,
       NULLIF(x.el ->> 'submittedById', '') AS submitted_by_id,
       ft_as_num(x.el #>> '{totals,gross}') AS gross,
       ft_as_num(x.el #>> '{totals,employerTaxes}') AS employer_taxes,
       ft_as_date(x.el #>> '{totals,enteredOn}') AS totals_entered_on,
       (SELECT count(*)::int FROM people p WHERE p.workspace_id = d.workspace_id AND ft_as_date(p.data ->> 'startDate') <= ft_as_date(x.el ->> 'periodEnd')
            AND (ft_as_date(p.data ->> 'endDate') IS NULL OR ft_as_date(p.data ->> 'endDate') >= ft_as_date(x.el ->> 'periodStart'))) AS people_in_period
  FROM workspace_docs d
 CROSS JOIN LATERAL jsonb_array_elements(ft_array(d.data -> 'payRuns')) WITH ORDINALITY AS x(el, n)
 WHERE d.key = 'company';
COMMENT ON VIEW v_pay_runs IS 'Pay runs on record, one row per pay period: marked submitted to the payroll provider, or with the totals entered from its register (payroll ran without the submitted mark).';

CREATE VIEW v_current_job WITH (security_invoker = true) AS
SELECT k.workspace_id,
       k.person_id AS id,
       (k.p).hire_number,
       (k.p).full_name,
       CASE WHEN (k.p).start_date > ft_today() THEN 'incoming'
            WHEN (k.p).end_date < ft_today() THEN 'former'
            WHEN k.on_leave THEN 'on_leave'
            ELSE 'active' END AS employment_state,
       coalesce((k.c).title, (k.p).title) AS title,
       coalesce((k.c).department_id, (k.p).department_id) AS department_id,
       (SELECT NULLIF(d.data ->> 'name', '') FROM departments d WHERE d.workspace_id = k.workspace_id AND d.id = coalesce((k.c).department_id, (k.p).department_id)) AS department_name,
       coalesce((k.c).level_id, (k.p).level_id) AS level_id,
       coalesce((k.c).manager_id, (k.p).manager_id) AS manager_id,
       (k.c).pay_type,
       (k.c).salary,
       (k.c).hourly_rate,
       (k.c).variable_pct,
       (k.c).id AS comp_id,
       (k.c).effective_on AS comp_effective_on,
       (k.c).reason AS comp_reason,
       (k.p).start_date,
       (k.p).end_date
  FROM (SELECT u.workspace_id,
               u.person_id,
               bool_or(u.step = 'person') AS is_person,
               (array_agg(u.p) FILTER (WHERE u.step = 'person'))[1] AS p,
               (array_agg(u.c ORDER BY (u.c).effective_on DESC, u.pos DESC) FILTER (WHERE u.step = 'comp'))[1] AS c,
               bool_or(u.step = 'leave') AS on_leave
          FROM (SELECT p.workspace_id, p.id AS person_id, 'person' AS step, p, NULL::v_comp AS c, NULL::integer AS pos
                  FROM v_people p
                UNION ALL
                SELECT c.workspace_id, c.person_id, 'comp', NULL, c, r.pos
                  FROM v_comp c
                  JOIN comp r ON r.workspace_id = c.workspace_id AND r.id = c.id
                 WHERE c.effective_on <= ft_today()
                UNION ALL
                SELECT l.workspace_id, NULLIF(l.data ->> 'personId', ''), 'leave', NULL, NULL, NULL
                  FROM leave_cases l
                 WHERE ft_as_date(l.data ->> 'startDate') <= ft_today()
                   AND NULLIF(l.data ->> 'returnedOn', '') IS NULL
                   AND (NULLIF(l.data ->> 'expectedReturn', '') IS NULL OR ft_as_date(l.data ->> 'expectedReturn') > ft_today())) u
         GROUP BY u.workspace_id, u.person_id) k
 WHERE k.is_person;
COMMENT ON VIEW v_current_job IS 'Each person''s job and pay today: the newest comp row effective on or before ft_today() (today in Pacific time, or the day in first_twenty.today), else nothing yet (an incoming hire). Title and department fall back to the person record.';

CREATE VIEW v_hire_journey WITH (security_invoker = true) AS
SELECT h.workspace_id,
       h.application_id,
       (h.a).job_id,
       j.title AS job_title,
       (h.a).candidate_id,
       concat_ws(' ', cand.first_name, cand.last_name) AS candidate_name,
       cand.source,
       (h.a).applied_on,
       (h.a).closed_on AS hired_on,
       (h.a).closed_on - (h.a).applied_on AS days_to_hire,
       (h.o).id AS offer_id,
       (h.o).sent_on AS offer_sent_on,
       (h.o).decided_on AS offer_accepted_on,
       (h.o).pay_type AS offer_pay_type,
       (h.o).salary AS offer_salary,
       (h.o).hourly_rate AS offer_hourly_rate,
       (h.o).equity_shares AS offer_shares,
       (h.p).id AS person_id,
       (h.p).hire_number,
       (h.p).full_name AS person_name,
       (h.p).start_date,
       (h.hc).id AS hire_comp_id,
       (h.hc).effective_on AS hire_comp_effective_on,
       (h.hc).salary AS hire_salary,
       (h.hc).hourly_rate AS hire_hourly_rate,
       (h.ob).id AS onboarding_checklist_id,
       (h.ob).tasks_total AS onboarding_tasks_total,
       (h.ob).tasks_done AS onboarding_tasks_done,
       (h.ob).tasks_open AS onboarding_tasks_open,
       (h.ob).completed_on AS onboarding_completed_on,
       pr.period_start AS first_pay_period_start,
       pr.period_end AS first_pay_period_end,
       pr.payday AS first_payday
  FROM (SELECT u.workspace_id,
               u.application_id,
               bool_or(u.step = 'application') AS is_hire,
               (array_agg(u.a) FILTER (WHERE u.step = 'application'))[1] AS a,
               (array_agg(u.o ORDER BY (u.o).decided_on DESC NULLS LAST, (u.o).id) FILTER (WHERE u.step = 'offer'))[1] AS o,
               (array_agg(u.p ORDER BY (u.p).id COLLATE "C") FILTER (WHERE u.step = 'person'))[1] AS p,
               (array_agg(u.hc ORDER BY (u.p).id COLLATE "C") FILTER (WHERE u.step = 'person'))[1] AS hc,
               (array_agg(u.ob ORDER BY (u.p).id COLLATE "C") FILTER (WHERE u.step = 'person'))[1] AS ob
          FROM (SELECT a.workspace_id, a.id AS application_id, 'application' AS step, a, NULL::v_offers AS o, NULL::v_people AS p, NULL::v_comp AS hc, NULL::v_checklists AS ob
                  FROM v_applications a
                 WHERE a.status = 'hired'
                UNION ALL
                SELECT o.workspace_id, o.application_id, 'offer', NULL, o, NULL, NULL, NULL
                  FROM v_offers o
                 WHERE o.status = 'accepted'
                UNION ALL
                -- Each hired person with their starting pay row and onboarding checklist, grouped the same way.
                SELECT s.workspace_id, (s.p).from_application_id, 'person', NULL, NULL, s.p, s.hc, s.ob
                  FROM (SELECT v.workspace_id,
                               v.person_id,
                               bool_or(v.step = 'person') AS is_person,
                               (array_agg(v.p) FILTER (WHERE v.step = 'person'))[1] AS p,
                               (array_agg(v.hc ORDER BY (v.hc).effective_on, (v.hc).id) FILTER (WHERE v.step = 'comp'))[1] AS hc,
                               (array_agg(v.ob ORDER BY (v.ob).created_on, (v.ob).id) FILTER (WHERE v.step = 'checklist'))[1] AS ob
                          FROM (SELECT p.workspace_id, p.id AS person_id, 'person' AS step, p, NULL::v_comp AS hc, NULL::v_checklists AS ob
                                  FROM v_people p
                                 WHERE p.from_application_id IS NOT NULL
                                UNION ALL
                                SELECT c.workspace_id, c.person_id, 'comp', NULL, c, NULL
                                  FROM v_comp c
                                 WHERE c.reason = 'hire'
                                UNION ALL
                                SELECT k.workspace_id, k.person_id, 'checklist', NULL, NULL, k
                                  FROM v_checklists k
                                 WHERE k.kind = 'onboarding') v
                         GROUP BY v.workspace_id, v.person_id) s
                 WHERE s.is_person) u
         GROUP BY u.workspace_id, u.application_id) h
  LEFT JOIN v_jobs j ON j.workspace_id = h.workspace_id AND j.id = (h.a).job_id
  LEFT JOIN v_candidates cand ON cand.workspace_id = h.workspace_id AND cand.id = (h.a).candidate_id
  LEFT JOIN LATERAL (
        SELECT r.period_start, r.period_end, r.payday
          FROM v_pay_runs r
         WHERE r.workspace_id = h.workspace_id
           AND r.period_start <= (h.p).start_date AND r.period_end >= (h.p).start_date
           AND ((h.p).end_date IS NULL OR r.period_start <= (h.p).end_date)
           AND (r.submitted_on IS NOT NULL OR r.totals_entered_on IS NOT NULL)
         ORDER BY r.period_start
         LIMIT 1) pr ON true
 WHERE h.is_hire;
COMMENT ON VIEW v_hire_journey IS 'One row per hire (an application marked hired): job, application, accepted offer, person, starting pay row, onboarding checklist and the pay run whose period holds the start date (null when that period is not on record, as for people paid before the company kept pay runs in the app, or a hire who never started). A missing step shows as nulls; v_integrity_problems says which.';

CREATE VIEW v_pipeline_funnel WITH (security_invoker = true) AS
SELECT s.workspace_id,
       s.job_id,
       s.job_title,
       s.job_status,
       s.stage_position,
       s.stage_id,
       s.stage_name,
       s.stage_kind,
       count(a.id) FILTER (WHERE a.stage_id = s.stage_id)::int AS in_stage,
       count(a.id) FILTER (WHERE a.stage_id = s.stage_id AND a.status = 'active')::int AS active,
       count(a.id) FILTER (WHERE a.stage_id = s.stage_id AND a.status = 'rejected')::int AS rejected,
       count(a.id) FILTER (WHERE a.stage_id = s.stage_id AND a.status = 'withdrawn')::int AS withdrawn,
       count(a.id) FILTER (WHERE a.stage_id = s.stage_id AND a.status = 'hired')::int AS hired,
       count(a.id) FILTER (WHERE EXISTS (SELECT 1 FROM v_application_stages h
                                          WHERE h.workspace_id = a.workspace_id AND h.application_id = a.id AND h.stage_id = s.stage_id))::int AS reached
  FROM (SELECT j.workspace_id,
               j.id AS job_id,
               NULLIF(j.data ->> 'title', '') AS job_title,
               NULLIF(j.data ->> 'status', '') AS job_status,
               x.n::int AS stage_position,
               NULLIF(x.el ->> 'id', '') AS stage_id,
               NULLIF(x.el ->> 'name', '') AS stage_name,
               NULLIF(x.el ->> 'kind', '') AS stage_kind
          FROM jobs j
         CROSS JOIN LATERAL jsonb_array_elements(ft_array(j.data -> 'stages')) WITH ORDINALITY AS x(el, n)) s
  LEFT JOIN v_applications a ON a.workspace_id = s.workspace_id AND a.job_id = s.job_id
 GROUP BY s.workspace_id, s.job_id, s.job_title, s.job_status, s.stage_position, s.stage_id, s.stage_name, s.stage_kind;
COMMENT ON VIEW v_pipeline_funnel IS 'Applications per job and stage, in the job''s stage order: in_stage are there now (any status), reached ever entered it (from the stage history).';

CREATE VIEW v_headcount_by_month WITH (security_invoker = true) AS
SELECT m.workspace_id,
       m.month,
       m.month_end,
       count(p.id) FILTER (WHERE p.start_date <= m.month_end AND (p.end_date IS NULL OR p.end_date >= m.month_end))::int AS headcount,
       count(p.id) FILTER (WHERE p.start_date BETWEEN m.month AND m.month_end)::int AS starts,
       count(p.id) FILTER (WHERE p.end_date BETWEEN m.month AND m.month_end)::int AS departures
  FROM (SELECT b.workspace_id, g.month::date AS month, (g.month + interval '1 month' - interval '1 day')::date AS month_end
          FROM (SELECT workspace_id,
                       date_trunc('month', min(start_date))::timestamp AS first_month,
                       date_trunc('month', greatest(max(start_date), max(end_date), ft_today()))::timestamp AS last_month
                  FROM v_people
                 WHERE start_date IS NOT NULL
                 GROUP BY workspace_id) b
         CROSS JOIN LATERAL generate_series(b.first_month, b.last_month, interval '1 month') AS g(month)) m
  LEFT JOIN v_people p ON p.workspace_id = m.workspace_id
 GROUP BY m.workspace_id, m.month, m.month_end;
COMMENT ON VIEW v_headcount_by_month IS 'W-2 headcount on the last day of each month (contractors never count), with the starts and last days in the month, from the first start to this month or the latest start or last day.';

CREATE VIEW v_integrity_problems WITH (security_invoker = true) AS
SELECT p.workspace_id, p.code, p.severity, p.collection, p.record_id, p.field, p.other_id
  FROM (
  SELECT r.workspace_id, 'broken_reference', 'failure', 'departments', r.id, 'headId', x.v
    FROM departments r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'headId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'bands', r.id, 'familyId', x.v
    FROM bands r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'familyId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM families t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'bands', r.id, 'levelId', x.v
    FROM bands r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'levelId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM levels t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'managerId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'managerId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'self_reference', 'failure', 'people', r.id, 'managerId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'managerId', '') AS v) x
   WHERE x.v = r.id
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'departmentId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'departmentId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM departments t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'familyId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'familyId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM families t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'levelId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'levelId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM levels t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'locationId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'locationId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM locations t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'fromCandidateId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'fromCandidateId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM candidates t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'fromApplicationId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'fromApplicationId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM applications t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'rehireOfPersonId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'rehireOfPersonId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'fromContractorId', x.v
    FROM people r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'fromContractorId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM contractors t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'people', r.id, 'separation.handoffs[].toId', x.v
    FROM people r
   CROSS JOIN LATERAL jsonb_array_elements(ft_array((r.data -> 'separation') -> 'handoffs')) AS e1(el)
   CROSS JOIN LATERAL (SELECT NULLIF(e1.el ->> 'toId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'comp', r.id, 'personId', x.v
    FROM comp r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'personId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'comp', r.id, 'levelId', x.v
    FROM comp r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'levelId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM levels t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'comp', r.id, 'managerId', x.v
    FROM comp r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'managerId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'comp', r.id, 'departmentId', x.v
    FROM comp r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'departmentId', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM departments t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'comp', r.id, 'approvedById', x.v
    FROM comp r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'approvedById', '') AS v) x
   WHERE x.v IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'grants', r.id, 'personId', x.v
    FROM grants r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'personId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
     AND NULLIF(r.data ->> 'holderType', '') IN ('employee')
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'grants', r.id, 'personId', x.v
    FROM grants r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'personId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM candidates t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
     AND NULLIF(r.data ->> 'holderType', '') IN ('candidate')
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'grants', r.id, 'personId', x.v
    FROM grants r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'personId', '') AS v) x
   WHERE (x.v IS NULL OR NOT (EXISTS (SELECT 1 FROM contractors t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)))
     AND NULLIF(r.data ->> 'holderType', '') IN ('advisor', 'contractor')
  UNION
  SELECT r.workspace_id, 'broken_reference', 'failure', 'grants', r.id, 'fromOfferId', x.v
    FROM grants r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'fromOfferId', '') AS v) x
