   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'stageId', '') AS v) x
   WHERE x.v IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ft_array(p.data -> 'stages')) AS l0(el) WHERE NULLIF(l0.el ->> 'id', '') = x.v)
  UNION
  SELECT r.workspace_id, 'unknown_stage', 'failure', 'applications', r.id, 'history[].stageId', x.v
