   CROSS JOIN LATERAL jsonb_array_elements(ft_array(r.data -> 'history')) AS e0(el)
   CROSS JOIN LATERAL (SELECT NULLIF(e0.el ->> 'stageId', '') AS v) x
   WHERE x.v IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ft_array(p.data -> 'stages')) AS l0(el) WHERE NULLIF(l0.el ->> 'id', '') = x.v)
  UNION
  SELECT r.workspace_id, 'unknown_stage', 'failure', 'jobs', r.id, 'interviewPlan[].stageId', x.v
    FROM jobs r
   CROSS JOIN LATERAL jsonb_array_elements(ft_array(r.data -> 'interviewPlan')) AS e0(el)
   CROSS JOIN LATERAL (SELECT NULLIF(e0.el ->> 'stageId', '') AS v) x
   WHERE x.v IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ft_array(r.data -> 'stages')) AS l0(el) WHERE NULLIF(l0.el ->> 'id', '') = x.v)
  UNION
  SELECT r.workspace_id, 'not_on_panel', 'note', 'scorecards', r.id, 'interviewerId', x.v
    FROM scorecards r
    JOIN interviews p ON p.workspace_id = r.workspace_id AND p.id = NULLIF(r.data ->> 'interviewId', '')
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'interviewerId', '') AS v) x
   WHERE x.v IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ft_array(p.data -> 'interviewerIds')) AS l0(el) WHERE NULLIF(l0.el #>> '{}', '') = x.v)
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'failure', 'offers', r.id, 'applicationId.candidateId', t.id
    FROM offers r
    JOIN applications t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'applicationId', '')
   WHERE NULLIF(r.data ->> 'candidateId', '') IS DISTINCT FROM NULLIF(t.data ->> 'candidateId', '')
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'failure', 'offers', r.id, 'applicationId.jobId', t.id
    FROM offers r
    JOIN applications t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'applicationId', '')
   WHERE NULLIF(r.data ->> 'jobId', '') IS DISTINCT FROM NULLIF(t.data ->> 'jobId', '')
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'failure', 'offers', r.id, 'personId.fromApplicationId', t.id
    FROM offers r
    JOIN people t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'personId', '')
   WHERE NULLIF(r.data ->> 'applicationId', '') IS DISTINCT FROM NULLIF(t.data ->> 'fromApplicationId', '')
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'failure', 'people', r.id, 'fromApplicationId.candidateId', t.id
    FROM people r
    JOIN applications t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'fromApplicationId', '')
   WHERE NULLIF(r.data ->> 'fromCandidateId', '') IS DISTINCT FROM NULLIF(t.data ->> 'candidateId', '')
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'failure', 'scorecards', r.id, 'interviewId.applicationId', t.id
    FROM scorecards r
    JOIN interviews t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'interviewId', '')
   WHERE NULLIF(r.data ->> 'applicationId', '') IS DISTINCT FROM NULLIF(t.data ->> 'applicationId', '')
  UNION
  SELECT r.workspace_id, 'mismatched_link', 'note', 'plan', r.id, 'jobId.planSlotId', t.id
    FROM plan r
    JOIN jobs t ON t.workspace_id = r.workspace_id AND t.id = NULLIF(r.data ->> 'jobId', '')
   WHERE NULLIF(r.data ->> 'id', '') IS DISTINCT FROM NULLIF(t.data ->> 'planSlotId', '')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'people', r.id, 'startDate>endDate', NULL
    FROM people r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data ->> 'endDate')
     AND NOT coalesce(ft_as_date(r.data ->> 'endDate') = ft_as_date(r.data #>> '{separation,lastDay}'), false)
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'people', r.id, 'startDate>separation.lastDay', NULL
    FROM people r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data #>> '{separation,lastDay}')
     AND NOT coalesce(ft_as_date(r.data ->> 'endDate') = ft_as_date(r.data #>> '{separation,lastDay}'), false)
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'people', r.id, 'separation.noticeGivenOn>separation.lastDay', NULL
    FROM people r
   WHERE ft_as_date(r.data #>> '{separation,noticeGivenOn}') > ft_as_date(r.data #>> '{separation,lastDay}')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'contractors', r.id, 'startOn>endOn', NULL
    FROM contractors r
   WHERE ft_as_date(r.data ->> 'startOn') > ft_as_date(r.data ->> 'endOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'jobs', r.id, 'openedOn>closedOn', NULL
    FROM jobs r
   WHERE ft_as_date(r.data ->> 'openedOn') > ft_as_date(r.data ->> 'closedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'jobs', r.id, 'postedOn>closedOn', NULL
    FROM jobs r
   WHERE ft_as_date(r.data ->> 'postedOn') > ft_as_date(r.data ->> 'closedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'applications', r.id, 'appliedOn>stageEnteredOn', NULL
    FROM applications r
   WHERE ft_as_date(r.data ->> 'appliedOn') > ft_as_date(r.data ->> 'stageEnteredOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'applications', r.id, 'appliedOn>closedOn', NULL
    FROM applications r
   WHERE ft_as_date(r.data ->> 'appliedOn') > ft_as_date(r.data ->> 'closedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'offers', r.id, 'createdOn>sentOn', NULL
    FROM offers r
   WHERE ft_as_date(r.data ->> 'createdOn') > ft_as_date(r.data ->> 'sentOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'offers', r.id, 'sentOn>decidedOn', NULL
    FROM offers r
   WHERE ft_as_date(r.data ->> 'sentOn') > ft_as_date(r.data ->> 'decidedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'offers', r.id, 'createdOn>decidedOn', NULL
    FROM offers r
   WHERE ft_as_date(r.data ->> 'createdOn') > ft_as_date(r.data ->> 'decidedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'note', 'offers', r.id, 'sentOn>expiresOn', NULL
    FROM offers r
   WHERE ft_as_date(r.data ->> 'sentOn') > ft_as_date(r.data ->> 'expiresOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'note', 'grants', r.id, 'proposedOn>boardApprovedOn', NULL
    FROM grants r
   WHERE ft_as_date(r.data ->> 'proposedOn') > ft_as_date(r.data ->> 'boardApprovedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'checklists', r.id, 'createdOn>completedOn', NULL
    FROM checklists r
   WHERE ft_as_date(r.data ->> 'createdOn') > ft_as_date(r.data ->> 'completedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'candidates', r.id, 'createdOn>retainUntil', NULL
    FROM candidates r
   WHERE ft_as_date(r.data ->> 'createdOn') > ft_as_date(r.data ->> 'retainUntil')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'timeOffRequests', r.id, 'startDate>endDate', NULL
    FROM time_off_requests r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data ->> 'endDate')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'timeOffRequests', r.id, 'requestedOn>decidedOn', NULL
    FROM time_off_requests r
   WHERE ft_as_date(r.data ->> 'requestedOn') > ft_as_date(r.data ->> 'decidedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'leaveCases', r.id, 'startDate>expectedReturn', NULL
    FROM leave_cases r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data ->> 'expectedReturn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'leaveCases', r.id, 'startDate>returnedOn', NULL
    FROM leave_cases r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data ->> 'returnedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'leaveCases', r.id, 'startDate>endedOn', NULL
    FROM leave_cases r
   WHERE ft_as_date(r.data ->> 'startDate') > ft_as_date(r.data ->> 'endedOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'recordsRequests', r.id, 'receivedOn>dueOn', NULL
    FROM records_requests r
   WHERE ft_as_date(r.data ->> 'receivedOn') > ft_as_date(r.data ->> 'dueOn')
  UNION
  SELECT r.workspace_id, 'date_order', 'failure', 'recordsRequests', r.id, 'receivedOn>fulfilledOn', NULL
    FROM records_requests r
   WHERE ft_as_date(r.data ->> 'receivedOn') > ft_as_date(r.data ->> 'fulfilledOn')
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'failure', 'people', d.id, 'hireNumber', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM people r
           CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'hireNumber', '') AS v) x
           WHERE x.v IS NOT NULL) d
   WHERE d.id <> d.first_id
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'failure', 'people', d.id, 'fromApplicationId', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM people r
           CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'fromApplicationId', '') AS v) x
           WHERE x.v IS NOT NULL) d
   WHERE d.id <> d.first_id
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'failure', 'offers', d.id, 'applicationId', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM offers r
           CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'applicationId', '') AS v) x
           WHERE x.v IS NOT NULL
             AND NULLIF(r.data ->> 'status', '') IN ('accepted')) d
   WHERE d.id <> d.first_id
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'note', 'people', d.id, 'workEmail', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM people r
           CROSS JOIN LATERAL (SELECT lower(NULLIF(r.data ->> 'workEmail', '')) AS v) x
           WHERE x.v IS NOT NULL) d
   WHERE d.id <> d.first_id
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'note', 'people', d.id, 'payrollId', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM people r
           CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'payrollId', '') AS v) x
           WHERE x.v IS NOT NULL) d
   WHERE d.id <> d.first_id
  UNION
  SELECT d.workspace_id, 'duplicate_value', 'note', 'candidates', d.id, 'email', d.first_id
    FROM (SELECT r.workspace_id, r.id, first_value(r.id) OVER (PARTITION BY r.workspace_id, x.v ORDER BY r.id COLLATE "C") AS first_id
            FROM candidates r
           CROSS JOIN LATERAL (SELECT lower(NULLIF(r.data ->> 'email', '')) AS v) x
           WHERE x.v IS NOT NULL) d
   WHERE d.id <> d.first_id
  UNION
  SELECT r.workspace_id, 'stage_history_mismatch', 'failure', 'applications', r.id, 'stageId', NULLIF((ft_array(r.data -> 'history') -> -1) ->> 'stageId', '')
    FROM applications r
   WHERE jsonb_array_length(ft_array(r.data -> 'history')) > 0
     AND NULLIF((ft_array(r.data -> 'history') -> -1) ->> 'stageId', '') IS DISTINCT FROM NULLIF(r.data ->> 'stageId', '')
  UNION
  SELECT r.workspace_id, 'history_out_of_order', 'failure', 'applications', r.id, 'history[].at', NULL
    FROM applications r
   CROSS JOIN LATERAL (SELECT ft_as_date(h.el ->> 'at') AS at, lag(ft_as_date(h.el ->> 'at')) OVER (ORDER BY h.n) AS prev
                         FROM jsonb_array_elements(ft_array(r.data -> 'history')) WITH ORDINALITY AS h(el, n)) s
   WHERE s.at < s.prev
  UNION
  SELECT a.workspace_id, 'hire_missing_offer', 'note', 'applications', a.id, 'offers', NULL
    FROM applications a
   WHERE a.data ->> 'status' = 'hired'
     AND NOT EXISTS (SELECT 1 FROM offers o WHERE o.workspace_id = a.workspace_id AND o.data ->> 'applicationId' = a.id AND o.data ->> 'status' = 'accepted')
  UNION
  SELECT a.workspace_id, 'hire_missing_person', 'failure', 'applications', a.id, 'people', NULL
    FROM applications a
   WHERE a.data ->> 'status' = 'hired'
     AND NOT EXISTS (SELECT 1 FROM people p WHERE p.workspace_id = a.workspace_id AND p.data ->> 'fromApplicationId' = a.id)
  UNION
  SELECT a.workspace_id, 'hire_missing_comp', 'failure', 'applications', a.id, 'comp', p.id
    FROM applications a
    JOIN people p ON p.workspace_id = a.workspace_id AND p.data ->> 'fromApplicationId' = a.id
   WHERE a.data ->> 'status' = 'hired'
     AND NOT EXISTS (SELECT 1 FROM comp c WHERE c.workspace_id = p.workspace_id AND c.data ->> 'personId' = p.id AND c.data ->> 'reason' = 'hire')
  UNION
  SELECT a.workspace_id, 'hire_missing_checklist', 'note', 'applications', a.id, 'checklists', p.id
    FROM applications a
    JOIN people p ON p.workspace_id = a.workspace_id AND p.data ->> 'fromApplicationId' = a.id
   WHERE a.data ->> 'status' = 'hired'
     AND NOT EXISTS (SELECT 1 FROM checklists c WHERE c.workspace_id = p.workspace_id AND c.data ->> 'personId' = p.id AND c.data ->> 'kind' = 'onboarding')
  UNION
  SELECT i.workspace_id, 'unknown_step', 'note', 'interviews', i.id, 'stepId', NULLIF(i.data ->> 'stepId', '')
    FROM interviews i
    JOIN applications a ON a.workspace_id = i.workspace_id AND a.id = NULLIF(i.data ->> 'applicationId', '')
    JOIN jobs j ON j.workspace_id = a.workspace_id AND j.id = NULLIF(a.data ->> 'jobId', '')
   WHERE NULLIF(i.data ->> 'stepId', '') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ft_array(j.data -> 'interviewPlan')) AS s(el) WHERE s.el ->> 'id' = i.data ->> 'stepId')
  UNION
  SELECT d.workspace_id, 'broken_reference', 'failure', 'complianceStatus', e.key, 'ownerId', NULLIF(e.value ->> 'ownerId', '')
    FROM workspace_docs d
   CROSS JOIN LATERAL jsonb_each(ft_object(d.data)) AS e(key, value)
   WHERE d.key = 'complianceStatus'
     AND NULLIF(e.value ->> 'ownerId', '') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM people p WHERE p.workspace_id = d.workspace_id AND p.id = NULLIF(e.value ->> 'ownerId', ''))
  UNION
  SELECT r.workspace_id, 'broken_reference', 'note', 'activity', r.id, 'entityId', x.v
    FROM activity r
   CROSS JOIN LATERAL (SELECT NULLIF(r.data ->> 'entityId', '') AS v) x
   WHERE r.data ->> 'entityType' = 'equity'
     AND (x.v IS NULL OR (x.v <> 'equity' AND NOT EXISTS (SELECT 1 FROM grants t WHERE t.workspace_id = r.workspace_id AND t.id = x.v) AND NOT EXISTS (SELECT 1 FROM people t WHERE t.workspace_id = r.workspace_id AND t.id = x.v) AND NOT EXISTS (SELECT 1 FROM contractors t WHERE t.workspace_id = r.workspace_id AND t.id = x.v)
          AND NOT EXISTS (SELECT 1 FROM workspace_docs d CROSS JOIN LATERAL jsonb_array_elements(ft_array(d.data -> 'valuations') || ft_array(d.data -> 'poolIncreases')) AS s(el)
                           WHERE d.workspace_id = r.workspace_id AND d.key = 'equity' AND s.el ->> 'id' = x.v)))
  UNION
  SELECT p.workspace_id, 'manager_leaving', 'note', 'people', p.id, 'managerId', m.id
    FROM people p
    JOIN people m ON m.workspace_id = p.workspace_id AND m.id = NULLIF(p.data ->> 'managerId', '') AND m.id <> p.id
   WHERE ft_as_date(m.data ->> 'endDate') IS NOT NULL
     AND (ft_as_date(p.data ->> 'endDate') IS NULL OR ft_as_date(p.data ->> 'endDate') > ft_as_date(m.data ->> 'endDate'))
  ) AS p (workspace_id, code, severity, collection, record_id, field, other_id);
COMMENT ON VIEW v_integrity_problems IS 'What should never be true of the data, as rows: the checks of src/domain/integrity.ts (code, severity failure or note, the record and field, the other record involved). Empty when the data is consistent.';

-- The views only read. Every new relation gets the server role's write rights from its default
-- privileges (server/deploy/postgres-setup.sql), and a simple view would pass writes on to its table, so
-- those rights are taken back here: every role keeps SELECT only. The optional read-only login
-- (server/deploy/viewer-role.sql) gets SELECT when it exists here. npm run server:after-restore runs this
-- again after a restore (server/src/readmodel/privileges.ts).
DO $$
DECLARE
  v record;
  grantee text;
BEGIN
  FOR v IN
    SELECT format('public.%I', c.relname) AS name, c.relacl, c.relowner
      FROM pg_class c
     WHERE c.relnamespace = 'public'::regnamespace AND c.relkind = 'v'
       AND EXISTS (SELECT 1 FROM unnest(c.reloptions) AS o WHERE lower(o) IN ('security_invoker=true', 'security_invoker=on', 'security_invoker=1', 'security_invoker=yes'))
  LOOP
    FOR grantee IN
      SELECT DISTINCT CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END
        FROM aclexplode(v.relacl) AS a
       WHERE a.privilege_type <> 'SELECT' AND a.grantee <> v.relowner
    LOOP
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON %s FROM %s', v.name, grantee);
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'first_twenty_viewer') THEN
      EXECUTE format('GRANT SELECT ON %s TO first_twenty_viewer', v.name);
    END IF;
  END LOOP;
END
$$;
